import serial
import sys
import signal
import atexit

# Define a function to handle the cleanup on exit
def cleanup():
    try:
        ser.close()
    except NameError:
        pass  # ser might not be defined if the program exits before opening the serial port
    except Exception as e:
        print(f"Error closing serial port: {e}")

# Register the cleanup function to run on exit
atexit.register(cleanup)

# Define a function to handle the signal to exit
def signal_handler(sig, frame):
    cleanup()
    sys.exit(0)

# Register the signal handler
signal.signal(signal.SIGINT, signal_handler)

