import sys
import time
import board
import busio
from adafruit_ads1x15 import ADS1115
from gpiozero import LED
from picamera2 import Picamera2
import paho.mqtt.client as mqtt

# Set up the ADC
try:
    i2c = busio.I2C(board.SCL, board.SDA)
    ads = ADS1115(i2c, address=0x48)
except Exception as e:
    print(f"Error initializing ADC: {e}")
    sys.exit(1)

# Set up the camera
try:
    camera = Picamera2()
except Exception as e:
    print(f"Error initializing camera: {e}")
    sys.exit(1)

# Set up the LED
try:
    led = LED(17)
except Exception as e:
    print(f"Error initializing LED: {e}")
    sys.exit(1)

# Set up MQTT
try:
    client = mqtt.Client()
    client.connect("localhost")
except Exception as e:
    print(f"Error connecting to MQTT: {e}")
    sys.exit(1)

try:
    while True:
        try:
            reading = ads.read_adc(0, gain=1)
            if reading is None:
                print("Invalid reading")
                continue
            print(f"ADC reading: {reading}")
            client.publish("adc/reading", str(reading))
            time.sleep(0.5)
        except Exception as e:
            print(f"Error reading ADC: {e}")
            break
finally:
    # Release hardware resources
    try:
        ads.deinit()
    except Exception as e:
        print(f"Error deinitializing ADC: {e}")
    try:
        camera.close()
    except Exception as e:
        print(f"Error closing camera: {e}")
    try:
        led.close()
    except Exception as e:
        print(f"Error closing LED: {e}")
    try:
        client.disconnect()
    except Exception as e:
        print(f"Error disconnecting from MQTT: {e}")
    sys.exit(0)

