import sys
import serial
import time
import logging
import signal
import atexit
import gpiozero

# Set up logging
logging.basicConfig(level=logging.INFO)

# Set up signal handler for clean exit
def signal_handler(sig, frame):
    logging.info('Received signal to exit')
    exit_cleanly()
    sys.exit(0)

def exit_cleanly():
    # Release hardware resources
    try:
        ser.close()
    except NameError:
        pass  # ser not defined yet
    except serial.SerialException as e:
        logging.error(f'Failed to close serial port: {e}')

# Set up signal handler
signal.signal(signal.SIGINT, signal_handler)

# Set up serial port
try:
    ser = serial.Serial('/dev/ttyUSB0', 9600, timeout=0.1)
except serial.SerialException as e:
    logging.error(f'Failed to open serial port: {e}')
    exit_cleanly()
    sys.exit(1)

# Set up validity check function
def is_valid_reading(reading):
    # Replace this with your own validity check function
    return reading != b''

# Main loop
try:
    while True:
        try:
            reading = ser.readline()
            if reading:
                if is_valid_reading(reading):
                    print(reading.decode('utf-8'))
                else:
                    logging.warning(f'Rejected invalid reading: {reading}')
            else:
                logging.info('No reading available')
        except serial.SerialException as e:
            logging.error(f'Serial read error: {e}')
            exit_cleanly()
            sys.exit(1)
        time.sleep(0.1)
except KeyboardInterrupt:
    exit_cleanly()
    sys.exit(0)
